-- 使用帮助 FAQ：移动端「员工与权限」新增 1 条问答 roster-manage（店长如何用手机给员工排班并发布？）。
-- 背景：迁移 20261025.001-help-faq 只在两张表为空时灌种子，生产库已灌过，新问答需单独插入；合并 PR 不会自动改线上。
-- 内容与 Data/SeedData/help-faq-seed.json、apps/web/.../faqSnapshot.json 一致（由种子生成）；按 Code 判断是否已存在，可重复执行；只 INSERT，不改已有行。
-- SortOrder 取分组内当前最大值 + 10（种子里是下标 × 10，people 分组原有 0/10/20，所以这里是 30），追加在分组末尾，不挪动其他行。
-- 执行前请只读核对：目标库是生产 HBweb；移动端 people 分组存在；Code=roster-manage 尚不存在。
-- 回滚：DELETE FROM dbo.HelpFaqQuestion WHERE Code = N'roster-manage' AND CreatedBy = N'faq-sql-20261105';（公开接口有 5 分钟内存缓存）
SET XACT_ABORT ON;
SET NOCOUNT ON;
BEGIN TRANSACTION;

DECLARE @GroupGUID nvarchar(50) = (SELECT [GroupGUID] FROM [dbo].[HelpFaqGroup] WHERE [Tab] = N'mobile' AND [Code] = N'people' AND [IsDeleted] = 0);
IF @GroupGUID IS NULL
    THROW 51990, N'找不到移动端 people 分组（HelpFaqGroup），中止。', 1;

DECLARE @Now datetime2 = SYSUTCDATETIME();
DECLARE @SortOrder int = (SELECT ISNULL(MAX([SortOrder]), -10) + 10 FROM [dbo].[HelpFaqQuestion] WHERE [GroupGUID] = @GroupGUID);

IF NOT EXISTS (SELECT 1 FROM [dbo].[HelpFaqQuestion] WHERE [Code] = N'roster-manage')
    INSERT INTO [dbo].[HelpFaqQuestion]
        ([QuestionGUID], [GroupGUID], [Code], [TitleZh], [TitleEn], [WhereZh], [WhereEn],
         [StepsZh], [StepsEn], [TipsZh], [TipsEn], [RulesZh], [RulesEn], [RelatedZh], [RelatedEn],
         [Permissions], [SortOrder], [Status], [DraftJson], [PublishedAt], [Version],
         [CreatedAt], [CreatedBy], [UpdatedAt], [UpdatedBy], [IsDeleted])
    VALUES
        (CONVERT(nvarchar(50), NEWID()), @GroupGUID, N'roster-manage', N'店长如何用手机给员工排班并发布？', N'How does a store manager roster staff and publish the week in the app?', N'工作台 · 人员与管理 · [k:Attendance management|考勤管理] → [tab:Roster|排班]', N'Home · Staff & admin · [k:Attendance management|考勤管理] → [tab:Roster|排班]',
         N'["§排班前准备","在 [tab:Home|工作台] 的「人员与管理」里点 [k:Attendance management|考勤管理]，切到 [tab:Roster|排班] 页签（账号有打卡记录权限时，默认先打开 [tab:Punches|打卡记录]）。","管理多家分店时，点上方的分店按钮选要排班的分店（店长只能排自己主分店；管理员可选所有分店）。点标题两侧的 ‹ › 箭头切到要排的那一周，标题显示「N 年第 W 周」和日期范围。","§排班","表格里一行是一位员工、一列是一天。点员工那一行、那一天的格子，在 [d:Add shift|新增班次] 窗口里选一个常用班次（09:00–13:00、16:00–17:30、09:00–17:00、09:00–21:00、09:00–19:00），或用开始 / 结束时间旁的 ± 按钮每次调整 30 分钟；需要时调整 [d:Meal breaks|用餐] 次数、填 [i:Note|备注]，最后点 [p:Save|保存]（按钮上会显示这个班的工时）。","一次排多天或多人：点员工姓名，给这位员工 [d:Roster several days|批量排多天]；点表头的日期，给这一天 [d:Roster several staff|批量排多人]。选好时间并勾选日期 / 员工后，点底部的 [p:Add N shift(s)|新增 N 个班次]。已有班次、已批准请假或标了不能上班的日期 / 员工选不了。","想更快：表格上方的 [d:Add shift|添加班次] 一行放着常用班次，点一个再点要放的格子，或长按后拖到格子里；放下后提示条上有 [k:Undo|撤销]。已排好的班次要换位置，点开它，用 [k:Move to…|移到…] 或 [k:Copy to…|复制到…]，再点目标格子。","整周照搬：点 [k:Copy last week|复制上周]，确认后把上周的班次复制到本周（都是草稿；本周已有班次的员工和日期会跳过）。","§检查并发布","看表格上方的状态：[d:Draft · not published|草稿·未发布] 表示还有没发布的班次；「空缺 N 天」提示哪几天没有人上班。图例在表格下方，格子里的 ⚠︎ 表示班次和员工上报的时间冲突。","确认无误后点最下面的 [p:Publish week|发布本周]。出现「本周排班已发布」后，员工才能看到本周的正式排班。","要发到员工群：本周没有草稿时，状态旁会出现 [k:Export image|导出图片]，点开后点 [p:Share image|分享图片]，选择微信等应用发送。"]',
         N'["§Before you start","On [tab:Home|工作台], under “Staff & admin”, tap [k:Attendance management|考勤管理], then switch to the [tab:Roster|排班] tab (if your account can view punch records, [tab:Punches|打卡记录] opens first).","If you manage several stores, tap the store button at the top to pick the store (managers can roster their primary store only; admins can pick any store). Use the ‹ › arrows beside the title to move to the week you want; the title shows the week number and date range.","§Rostering","Each row is a staff member and each column is a day. Tap the cell for that person and day. In the [d:Add shift|新增班次] window, pick a common shift (09:00–13:00, 16:00–17:30, 09:00–17:00, 09:00–21:00, 09:00–19:00) or nudge the start / end time by 30 minutes with the ± buttons. Adjust [d:Meal breaks|用餐] and add a [i:Note|备注] if needed, then tap [p:Save|保存] (the button shows the shift’s hours).","To roster several days or several people at once, tap a staff name for [d:Roster several days|批量排多天], or tap a date in the header for [d:Roster several staff|批量排多人]. Pick the times and the days / staff, then tap [p:Add N shift(s)|新增 N 个班次]. Days or staff that already have a shift, approved leave, or are marked unavailable can’t be selected.","To go faster, use the [d:Add shift|添加班次] row of common shifts above the grid: tap one, then tap the target cell, or press and hold and drag it onto a cell. A bar then offers [k:Undo|撤销]. To rearrange an existing shift, open it and use [k:Move to…|移到…] or [k:Copy to…|复制到…], then tap the target cell.","To reuse last week, tap [k:Copy last week|复制上周] and confirm. Last week’s shifts are copied into this week as drafts; staff who already have a shift that day are skipped.","§Check and publish","Check the status above the grid: [d:Draft · not published|草稿·未发布] means some shifts are still unpublished, and “N day(s) unstaffed” shows the days nobody is rostered. The legend is under the grid; a ⚠︎ in a cell means the shift clashes with the times the employee reported.","When it looks right, tap [p:Publish week|发布本周] at the bottom. Once you see “This week’s roster is published.”, staff can see the official roster for the week.","To send it to the staff chat: when the week has no drafts, [k:Export image|导出图片] appears next to the status. Tap it, then tap [p:Share image|分享图片] and pick WeChat or another app."]',
         N'["新建的班次（单个、批量、拖放、复制上周）一律是草稿，员工看不到，必须点 [p:Publish week|发布本周] 才生效；已发布的班次修改或移动后保持有效，直接生效。之后又出现新草稿时，状态会变回「草稿·未发布」，要再发布一次。","一天要排两段班（如早班 + 晚班）：点开已有班次，在窗口顶部点 [k:Add another shift|再加一班]。同一格里时间重叠的班次放不进去。","格子里的 [d:Avail|可] / [d:No|不可] 是员工自己上报的可上班 / 不能上班时间，[d:Leave|假] 是已批准请假。班次落在这些时间之外只是提醒（格子出现 ⚠︎，拖放时会问 [k:Place anyway|仍然放下]），可以照排。","删除班次：点开班次，点窗口底部的 [k:Set as day off|设为休息]（或班次小标签右侧的 ×），确认 [p:Delete|删除] 后关联的待审批考勤会一并取消。已有打卡记录的班次不能移动或复制，只能删除。误删的班次可在 Web 后台「排班考勤」页的 [k:Deleted rosters|已删除排班] 里恢复，恢复后一般是草稿，要重新发布。","21 岁以下员工的名字旁会显示年龄。未满 16 岁员工的班次会按未成年用工规则检查：班次照常保存，但会提示「保留 N 条未成年用工提醒」、格子里显示 !，点页面上方的 [k:Minor employment reminders|未成年用工提醒待办] 查看。","其他店长默认不在表格里（已有班次的除外），要给他们排班时点状态行的 [k:Other store managers|其他店长] 显示。想一屏看全周，点卡片右上角的全屏图标 [k:Full screen|全屏维护]。"]',
         N'["Every new shift (single, bulk, drag and drop, or copied from last week) starts as a draft that staff cannot see until you tap [p:Publish week|发布本周]. Editing or moving a shift that is already published keeps it active right away. If new drafts appear later, the status goes back to “Draft · not published”, so publish again.","For a split day (for example morning + evening), open an existing shift and tap [k:Add another shift|再加一班] at the top of the window. Overlapping shifts can’t go in the same cell.","[d:Avail|可] / [d:No|不可] in a cell are the times the employee reported as available / unavailable, and [d:Leave|假] is approved leave. A shift outside those times is only a warning (the cell shows ⚠︎ and dragging asks [k:Place anyway|仍然放下]); you can still roster it.","To delete a shift, open it, tap [k:Set as day off|设为休息] at the bottom of the window (or the × on the shift chip), then confirm [p:Delete|删除]; related pending attendance approvals are cancelled. A shift that already has punch records can be deleted but not moved or copied. An accidental delete can be restored under [k:Deleted rosters|已删除排班] on the back-office Rosters and attendance page; a restored shift is normally a draft, so publish again.","Staff under 21 show their age beside their name. Shifts for staff under 16 are checked against the minor employment rules: the shift is still saved, but you see “Shift saved with N minor employment warning(s)” and a ! in the cell. Tap [k:Minor employment reminders|未成年用工提醒待办] above the grid to review them.","Other store managers are hidden from the grid unless they already have a shift; tap [k:Other store managers|其他店长] in the status row to show them. To see the whole week on one screen, tap the full-screen icon at the top right of the card ([k:Full screen|全屏维护])."]',
         NULL, NULL, NULL, NULL,
         N'["Attendance.Schedule.ViewStore","Attendance.Schedule.EditManagedStore"]', @SortOrder, N'Published', NULL, @Now, 1,
         @Now, N'faq-sql-20261105', @Now, N'faq-sql-20261105', 0);

SELECT q.[Code], q.[SortOrder], q.[Status] FROM [dbo].[HelpFaqQuestion] q WHERE q.[GroupGUID] = @GroupGUID ORDER BY q.[SortOrder];

COMMIT TRANSACTION;
